      "ram_gb": 4
    }
  },
  "window_allocations": [
    {
      "window_id": "window_1",
      "minutes": [0, 5],
      "tasks": ["stream_restore", "ingestion_repair", "feature_backfill_a", "feature_backfill_b"],
      "resource_totals": {
        "cpu": 16,
        "ram_gb": 32
      }
    },
    {
      "window_id": "window_2",
      "minutes": [5, 10],
      "tasks": ["analytics_rollup"],
      "resource_totals": {
        "cpu": 7,
        "ram_gb": 14
      }
    },
    {
      "window_id": "window_3",
      "minutes": [10, 15],
      "tasks": ["analytics_rollup"],
      "resource_totals": {
        "cpu": 7,
        "ram_gb": 14
      }
    },
    {
      "window_id": "window_4",
      "minutes": [15, 20],
